import {
	Button,
	Container,
	Text,
	Title,
	Modal,
	TextInput,
	Group,
	Card,
	ActionIcon,
	Code,
  } from '@mantine/core';
  import { useState, useRef, useEffect } from 'react';
  import { MoonStars, Sun, Trash } from 'tabler-icons-react';
  
  import {
	MantineProvider,
	ColorSchemeProvider,
	ColorScheme,
  } from '@mantine/core';
  import { useColorScheme } from '@mantine/hooks';
  import { useHotkeys, useLocalStorage } from '@mantine/hooks';
  
  export default function App() {
	const [tasks, setTasks] = useState([]);
	const [opened, setOpened] = useState(false);
  
	const preferredColorScheme = useColorScheme();
	const [colorScheme, setColorScheme] = useLocalStorage({
	  key: 'mantine-color-scheme',
	  defaultValue: 'light',
	  getInitialValueInEffect: true,
	});
	const toggleColorScheme = value =>
	  setColorScheme(value || (colorScheme === 'dark' ? 'light' : 'dark'));
  
	useHotkeys([['mod+J', () => toggleColorScheme()]]);
  
	const taskTitle = useRef('');
	const taskSummary = useRef('');
  
	function createTask() {
	  // Crée une nouvelle tâche en copiant l'état actuel des tâches
	  setTasks([
		...tasks,
		{
		  title: taskTitle.current.value,
		  summary: taskSummary.current.value,
		},
	  ]);
  
	  saveTasks([
		...tasks,
		{
		  title: taskTitle.current.value,
		  summary: taskSummary.current.value,
		},
	  ]);
	}
  
	function deleteTask(index) {
	  var clonedTasks = [...tasks];
	  clonedTasks.splice(index, 1);
	  setTasks(clonedTasks);
	  saveTasks([...clonedTasks]);
	}
  
	function loadTasks() {
	  let loadedTasks = localStorage.getItem('tasks');
	  let tasks = JSON.parse(loadedTasks);
	  if (tasks) {
		setTasks(tasks);
	  }
	}
  
	function saveTasks(tasks) {
	  localStorage.setItem('tasks', JSON.stringify(tasks));
	}
  
	useEffect(() => {
	  loadTasks();
	}, []);
  
	return (
	  <ColorSchemeProvider colorScheme={colorScheme} toggleColorScheme={toggleColorScheme}>
		<MantineProvider theme={{ colorScheme, defaultRadius: 'md' }} withGlobalStyles withNormalizeCSS>
		  <div className='App'>
			<Modal
			  data-cy="task-modal" // Ajout d'un data-cy pour identifier la modale d'ajout
			  opened={opened}
			  size={'md'}
			  title={'New Task'}
			  withCloseButton={false}
			  onClose={() => {
				setOpened(false);
			  }}
			  centered
			>
			  <TextInput
				data-cy="task-title-input" // Permet de cibler le champ de saisie du titre
				mt={'md'}
				ref={taskTitle}
				placeholder={'Task Title'}
				required
				label={'Title'}
			  />
			  <TextInput
				data-cy="task-summary-input" // Permet de cibler le champ de saisie du résumé
				ref={taskSummary}
				mt={'md'}
				placeholder={'Task Summary'}
				label={'Summary'}
			  />
			  <Group mt={'md'} position={'apart'}>
				<Button
				  data-cy="cancel-button" // Bouton Cancel dans la modale
				  onClick={() => {
					setOpened(false);
				  }}
				  variant={'subtle'}
				>
				  Cancel
				</Button>
				<Button
				  data-cy="create-task-button" // Bouton Create Task dans la modale
				  onClick={() => {
					createTask();
					setOpened(false);
				  }}
				>
				  Create Task
				</Button>
			  </Group>
			</Modal>
			<Container size={550} my={40}>
			  <Group position={'apart'}>
				<Title
				  data-cy="page-title" // Ajout d'un attribut pour le titre de la page
				  sx={theme => ({
					fontFamily: `Greycliff CF, ${theme.fontFamily}`,
					fontWeight: 900,
				  })}
				>
				  My Tasks
				</Title>
				<ActionIcon
				  data-cy="theme-toggle" // Bouton de basculement du thème
				  color={'blue'}
				  onClick={() => toggleColorScheme()}
				  size='lg'
				>
				  {colorScheme === 'dark' ? (
					<Sun size={16} />
				  ) : (
					<MoonStars size={16} />
				  )}
				</ActionIcon>
			  </Group>
			  {tasks.length > 0 ? (
				tasks.map((task, index) => {
				  if (task.title) {
					return (
					  <Card data-cy="task-card" withBorder key={index} mt={'sm'}>
						<Group position={'apart'}>
						  <Text weight={'bold'}>{task.title}</Text>
						  <ActionIcon
							data-cy="delete-task-button" // Bouton de suppression de tâche
							onClick={() => {
							  deleteTask(index);
							}}
							color={'red'}
							variant={'transparent'}
						  >
							<Trash />
						  </ActionIcon>
						</Group>
						<Text color={'dimmed'} size={'md'} mt={'sm'}>
						  {task.summary ? task.summary : 'No summary was provided for this task'}
						</Text>
					  </Card>
					);
				  }
				})
			  ) : (
				<Text data-cy="empty-message" size={'lg'} mt={'md'} color={'dimmed'}>
				  You have no tasks
				</Text>
			  )}
			  <Button
				data-cy="new-task-button" // Bouton pour ouvrir la modale d'ajout de tâche
				onClick={() => {
				  setOpened(true);
				}}
				fullWidth
				mt={'md'}
			  >
				New Task
			  </Button>
			</Container>
		  </div>
		</MantineProvider>
	  </ColorSchemeProvider>
	);
  }
